Item.method_code:
const canDelegateFieldName = 'can_delegate';
const consolidateFieldName = 'consolidate_ondelegate';

let canDelegateField;
if (this.tagName && this.tagName.toUpperCase == 'INPUT') {
	canDelegateField = this;
} else {
	canDelegateField = getInputByName(canDelegateFieldName);
}
if (!canDelegateFieldName) {
	return true;
}

const consolidateField = getInputByName(consolidateFieldName);
if (!consolidateField) {
	return true;
}

if (consolidateField.checked && !canDelegateField.checked) {consolidateField.checked = false;}
consolidateField.disabled = !canDelegateField.checked;
return true;

function getInputByName(inputName) {
	const allFields = document.getElementsByName(inputName);
	let requiredField;
	for (let i = 0; i < allFields.length; i++) {
		if (allFields[i].tagName.toUpperCase() == 'INPUT') {
			requiredField = allFields[i];
		}
	}
	return requiredField;
}
